apply plugin: "com.android.application"
apply plugin: "org.jetbrains.kotlin.android"
apply plugin: "org.jetbrains.kotlin.kapt"
apply plugin: "com.facebook.react"

// Add the Google Services plugin dependency
// This is used exclusively for sending benchmarks (with user consent) to Hugging Face Spaces via Firebase.
// Firebase is used for App Check functionality, allowing unauthenticated users to submit their benchmark data securely.
apply plugin: "com.google.gms.google-services"

apply from: "../../node_modules/react-native-config/android/dotenv.gradle"

/**
 * This is the configuration block to customize your React Native Android app.
 * By default you don't need to apply any configuration, just uncomment the lines you need.
 */
react {
    /* Folders */
    //   The root of your project, i.e. where "package.json" lives. Default is '../..'
    // root = file("../../")
    //   The folder where the react-native NPM package is. Default is ../../node_modules/react-native
    // reactNativeDir = file("../../node_modules/react-native")
    //   The folder where the react-native Codegen package is. Default is ../../node_modules/@react-native/codegen
    // codegenDir = file("../../node_modules/@react-native/codegen")
    //   The cli.js file which is the React Native CLI entrypoint. Default is ../../node_modules/react-native/cli.js
    // cliFile = file("../../node_modules/react-native/cli.js")

    /* Variants */
    //   The list of variants to that are debuggable. For those we're going to
    //   skip the bundling of the JS bundle and the assets. By default is just 'debug'.
    //   If you add flavors like lite, prod, etc. you'll have to list your debuggableVariants.
    // debuggableVariants = ["liteDebug", "prodDebug"]

    /* Bundling */
    //   A list containing the node command and its flags. Default is just 'node'.
    // nodeExecutableAndArgs = ["node"]
    //
    //   The command to run when bundling. By default is 'bundle'
    // bundleCommand = "ram-bundle"
    //
    //   The path to the CLI configuration file. Default is empty.
    // bundleConfig = file(../rn-cli.config.js)
    //
    //   The name of the generated asset file containing your JS bundle
    // bundleAssetName = "MyApplication.android.bundle"
    //
    //   The entry file for bundle generation. Default is 'index.android.js' or 'index.js'
    // entryFile = file("../js/MyApplication.android.js")
    //
    //   A list of extra flags to pass to the 'bundle' commands.
    //   See https://github.com/react-native-community/cli/blob/main/docs/commands.md#bundle
    // extraPackagerArgs = []

    /* Hermes Commands */
    //   The hermes compiler command to run. By default it is 'hermesc'
    // hermesCommand = "$rootDir/my-custom-hermesc/bin/hermesc"
    //
    //   The list of flags to pass to the Hermes compiler. By default is "-O", "-output-source-map"
    // hermesFlags = ["-O", "-output-source-map"]

    /* Autolinking */
    autolinkLibrariesWithApp()
}

/**
 * Set this to true to Run Proguard on Release builds to minify the Java bytecode.
 */
def enableProguardInReleaseBuilds = false

/**
 * The preferred build flavor of JavaScriptCore (JSC)
 *
 * For example, to use the international variant, you can use:
 * `def jscFlavor = io.github.react-native-community:jsc-android-intl:2026004.+`
 *
 * The international variant includes ICU i18n library and necessary data
 * allowing to use e.g. `Date.toLocaleString` and `String.localeCompare` that
 * give correct results when using with locales other than en-US. Note that
 * this variant is about 6MiB larger per architecture than default.
 */
def jscFlavor = 'io.github.react-native-community:jsc-android:2026004.+'

android {
    ndkVersion rootProject.ext.ndkVersion
    buildToolsVersion rootProject.ext.buildToolsVersion
    compileSdk rootProject.ext.compileSdkVersion

    namespace "com.pocketpal"
    defaultConfig {
        applicationId "com.pocketpalai"
        minSdkVersion rootProject.ext.minSdkVersion
        targetSdkVersion rootProject.ext.targetSdkVersion
        versionCode 153
        versionName "1.21.0"
        ndk {
            abiFilters "arm64-v8a", "x86_64"
        }
    }
    externalNativeBuild {
        cmake {
            // Replace RN's auto-injected default-app-setup CMakeLists so
            // we can link `hardware_info.cpp` (HardwareInfoModule's JNI
            // shim) into libappmodules.so. The replacement file must
            // include ReactNative-application.cmake — see jni/CMakeLists.txt.
            path file("src/main/jni/CMakeLists.txt")
        }
    }
    signingConfigs {
        debug {
            storeFile file('debug.keystore')
            storePassword 'android'
            keyAlias 'androiddebugkey'
            keyPassword 'android'
        }
        release {
            // Read signing credentials from .env file or environment variables
            def releaseStorePassword = project.env.get("APP_RELEASE_STORE_PASSWORD") ?: System.getenv("APP_RELEASE_STORE_PASSWORD")
            def releaseKeyPassword = project.env.get("APP_RELEASE_KEY_PASSWORD") ?: System.getenv("APP_RELEASE_KEY_PASSWORD")

            if (releaseStorePassword && releaseKeyPassword) {
                storeFile file("pocketpal-release-key.keystore")
                storePassword releaseStorePassword
                keyAlias "pocketpal_key_alias"
                keyPassword releaseKeyPassword
            }
        }
    }
    buildTypes {
        debug {
            signingConfig signingConfigs.debug
            // RN dev menu + Metro-served JS. Mirrors BuildConfig.DEBUG but
            // is independent of `debuggable`, so `releaseE2e` (which sets
            // debuggable=true for `adb run-as`) can still pin to false.
            buildConfigField "boolean", "USE_DEV_SUPPORT", "true"
        }
        release {
            // Caution! In production, you need to generate your own keystore file.
            // see https://reactnative.dev/docs/signed-apk-android.
            // Only use release signing config if credentials are available, otherwise use debug
            if (signingConfigs.release.storeFile != null) {
                signingConfig signingConfigs.release
            } else {
                // Fall back to debug signing for CI builds without credentials
                signingConfig signingConfigs.debug
                println "Warning: Release signing credentials not found, using debug keystore"
            }
            minifyEnabled enableProguardInReleaseBuilds
            proguardFiles getDefaultProguardFile("proguard-android-optimize.txt"), "proguard-rules.pro"
            buildConfigField "boolean", "USE_DEV_SUPPORT", "false"
        }
        releaseE2e {
            // E2E buildType: inherits 95% of release (Hermes, minify toggle,
            // proguard rules), then overrides:
            //   1. debuggable=true so `adb shell run-as com.pocketpalai.e2e`
            //      works for the benchmark-matrix preseed workflow.
            //   2. Debug signing — E2E builds are never shipped to stores.
            //   3. matchingFallbacks so dependencies resolve to their release
            //      variant (they don't publish a releaseE2e variant).
            initWith release
            debuggable true
            signingConfig signingConfigs.debug
            matchingFallbacks = ['release']
        }
    }

    testOptions {
        unitTests.includeAndroidResources = true
        unitTests.all {
            systemProperty "robolectric.conscryptMode", "OFF"
        }
    }

    flavorDimensions "distribution"
    productFlavors {
        prod {
            dimension "distribution"
            // applicationId stays as defaultConfig: com.pocketpalai
        }
        e2e {
            dimension "distribution"
            applicationIdSuffix ".e2e"
            // Effective applicationId: com.pocketpalai.e2e
            // Separate sandbox; installs side-by-side with prod.
        }
    }

    // Keep the variant matrix narrow: only prodDebug, prodRelease,
    // e2eDebug, and e2eReleaseE2e are valid combinations.
    //   - e2e + release  → unsigned E2E APK nobody asked for; drop it
    //   - prod + releaseE2e → debuggable prod APK that would ship via the
    //     prod applicationId; drop it
    // Without this filter, a bare `./gradlew assembleRelease` or
    // `assembleReleaseE2e` would build extra, confusing variants.
    variantFilter { variant ->
        def flavors = variant.flavors*.name
        def buildType = variant.buildType.name
        if (flavors.contains('e2e') && buildType == 'release') {
            setIgnore(true)
        }
        if (flavors.contains('prod') && buildType == 'releaseE2e') {
            setIgnore(true)
        }
    }
}

dependencies {
    // The version of react-native is set by the React Native Gradle Plugin
    implementation("com.facebook.react:react-android")

    if (hermesEnabled.toBoolean()) {
        implementation("com.facebook.react:hermes-android")
    } else {
        implementation jscFlavor
    }

    // The Firebase Android BoM (Bill of Materials) lets you manage all your Firebase library versions 
    // by specifying only one version — the BoM's version.
    implementation platform('com.google.firebase:firebase-bom:34.4.0')
    implementation 'com.google.firebase:firebase-appcheck-playintegrity'
    implementation 'com.google.firebase:firebase-appcheck-debug'

    // Room dependencies for DownloadModule
    def room_version = "2.8.2"
    implementation("androidx.room:room-runtime:$room_version")
    // Kotlin Extensions and Coroutines support for Room
    implementation("androidx.room:room-ktx:$room_version")
    kapt("androidx.room:room-compiler:$room_version")
    // WorkManager for DownloadModule
    implementation "androidx.work:work-runtime-ktx:2.10.5"
    // Lifecycle for DownloadModule
    implementation "androidx.lifecycle:lifecycle-livedata-ktx:2.9.4"
    // Coroutines for DownloadModule (wait)
    implementation "androidx.concurrent:concurrent-futures-ktx:1.3.0" 

    // Core library for AndroidX Jetpack - Needed for WindowCompat (we use for edge-to-edge)
    implementation "androidx.core:core-ktx:1.17.0"

    // OkHttp for DownloadModule (network requests)
    implementation("com.squareup.okhttp3:okhttp:4.12.0")

    testImplementation("junit:junit:4.13.2")
    testImplementation("org.robolectric:robolectric:4.16")
    testImplementation("androidx.test:core-ktx:1.7.0")
    testImplementation("androidx.room:room-testing:$room_version")
    testImplementation("androidx.sqlite:sqlite-bundled-jvm:2.6.1")
    testImplementation("com.squareup.okhttp3:mockwebserver:4.12.0")
    testImplementation("androidx.work:work-testing:2.10.5")
    testImplementation("org.jetbrains.kotlinx:kotlinx-coroutines-test:1.9.0")
}

// openiap-google's Compose helper (IapContext) is unreferenced; Gson is used by OpenIapModule.
configurations.matching {
    it.name.endsWith('CompileClasspath') || it.name.endsWith('RuntimeClasspath')
}.configureEach {
    exclude group: 'androidx.compose.ui'
    exclude group: 'androidx.compose.runtime'
}

project.ext.vectoricons = [
    iconFontNames: [ 'MaterialIcons.ttf', 'MaterialCommunityIcons.ttf'  ] // Specify font files
]

apply from: file("../../node_modules/react-native-vector-icons/fonts.gradle")
